-- Curated listening assessments based on the existing aligned ELLLO conversations.
-- Each unit reuses the lesson audio and transcript; do not expose answers before review.
INSERT INTO listening_units (lesson_id, audio_url, title, level, duration_seconds, content_json, published)
SELECT seed.lesson_id, sentence.audio_url, seed.title, lesson.level, seed.duration_seconds, seed.content_json, TRUE
FROM (VALUES
    (29, 18, 'A1 · Ngày đầu tiên ở trường', 34.2, '{"facts":[{"id":"F1","text":"Beth cảm thấy ngày đầu tiên ở trường rất tốt."},{"id":"F2","text":"Beth thấy các lớp học vui và giáo viên thân thiện."},{"id":"F3","text":"Giáo viên tiếng Anh của Beth là Mr. Wong."},{"id":"F4","text":"Giáo viên tiếng Tây Ban Nha của Beth là Mrs. Garcia; lớp của cô ấy rất vui."}],"questions":[{"id":"Q1","type":"MAIN_IDEA","text":"Cuộc trò chuyện chủ yếu nói về điều gì?","options":["Trải nghiệm học ở trường của Beth","Kế hoạch đi du lịch của Beth","Một bài kiểm tra khó"],"correct":0,"explanation":"Hai người nói về ngày đầu tiên, các lớp học và giáo viên của Beth."},{"id":"Q2","type":"DETAIL","text":"Beth nhận xét các lớp học của mình thế nào?","options":["Vui","Quá dài","Rất khó"],"correct":0,"explanation":"Beth nói các lớp học đều vui."},{"id":"Q3","type":"DETAIL","text":"Ai dạy tiếng Anh cho Beth?","options":["Mr. Wong","Mrs. Garcia","Tony"],"correct":0,"explanation":"Beth nói giáo viên tiếng Anh của mình là Mr. Wong."},{"id":"Q4","type":"DETAIL","text":"Ai dạy tiếng Tây Ban Nha cho Beth?","options":["Mrs. Garcia","Mr. Wong","Beth"],"correct":0,"explanation":"Beth nêu tên Mrs. Garcia là giáo viên tiếng Tây Ban Nha."},{"id":"Q5","type":"INFERENCE","text":"Beth có vẻ cảm thấy thế nào về trường mới?","options":["Hài lòng và hào hứng","Thất vọng","Muốn nghỉ học"],"correct":0,"explanation":"Beth khen trường, lớp học và các giáo viên."}]}'),
    (32, 1, 'A1 · Buổi sáng của tôi', 24.88, '{"facts":[{"id":"F1","text":"Người nói mô tả thói quen buổi sáng của mình."},{"id":"F2","text":"Người đó thức dậy lúc 6 giờ."},{"id":"F3","text":"Sau khi dậy, người đó tắm, mặc quần áo và ăn sáng."},{"id":"F4","text":"Người đó thích buổi sáng dù người kia thấy 6 giờ là sớm."}],"questions":[{"id":"Q1","type":"MAIN_IDEA","text":"Chủ đề chính của cuộc trò chuyện là gì?","options":["Thói quen buổi sáng","Kế hoạch cuối tuần","Bữa tối ở nhà"],"correct":0,"explanation":"Người nói kể những việc mình làm vào buổi sáng."},{"id":"Q2","type":"DETAIL","text":"Người nói thức dậy lúc mấy giờ?","options":["6 giờ","7 giờ","8 giờ"],"correct":0,"explanation":"Người đó nói mình dậy lúc 6 giờ."},{"id":"Q3","type":"DETAIL","text":"Việc nào được nhắc tới sau khi thức dậy?","options":["Tắm và ăn sáng","Đi bơi","Xem phim"],"correct":0,"explanation":"Người đó kể mình tắm, mặc quần áo và ăn sáng."},{"id":"Q4","type":"INFERENCE","text":"Người kia nghĩ gì về giờ thức dậy này?","options":["Khá sớm","Quá muộn","Rất bình thường"],"correct":0,"explanation":"Người kia ngạc nhiên và nói rằng như thế là sớm."},{"id":"Q5","type":"DETAIL","text":"Người nói cảm thấy thế nào về buổi sáng?","options":["Thích buổi sáng","Ghét buổi sáng","Không nói"],"correct":0,"explanation":"Người đó nói mình thích buổi sáng."}]}'),
    (34, 1, 'A2 · Công việc và đường đi làm', 31.8, '{"facts":[{"id":"F1","text":"Một người làm ở công ty công nghệ và thiết kế phần mềm."},{"id":"F2","text":"Người đó thích công việc của mình."},{"id":"F3","text":"Văn phòng mới của người đó ở trung tâm thành phố."},{"id":"F4","text":"Người đó đi làm bằng xe buýt và không có ô tô."}],"questions":[{"id":"Q1","type":"MAIN_IDEA","text":"Hai người chủ yếu trao đổi về điều gì?","options":["Công việc và cách đi làm","Một kỳ nghỉ hè","Bữa trưa ở văn phòng"],"correct":0,"explanation":"Họ nói về nghề nghiệp, nơi làm việc và phương tiện đi làm."},{"id":"Q2","type":"DETAIL","text":"Người được hỏi làm gì ở công ty?","options":["Thiết kế phần mềm","Bán ô tô","Dạy ngoại ngữ"],"correct":0,"explanation":"Người đó nói mình thiết kế phần mềm."},{"id":"Q3","type":"DETAIL","text":"Văn phòng nằm ở đâu?","options":["Ở trung tâm thành phố","Bên bờ sông","Gần sân bay"],"correct":0,"explanation":"Người đó làm tại văn phòng mới ở downtown."},{"id":"Q4","type":"DETAIL","text":"Người đó đi làm bằng gì?","options":["Xe buýt","Ô tô riêng","Xe đạp"],"correct":0,"explanation":"Người đó nói mình đi xe buýt."},{"id":"Q5","type":"INFERENCE","text":"Vì sao việc đi xe buýt phù hợp với người này?","options":["Người đó không có ô tô","Công ty cấm dùng ô tô","Xe buýt miễn phí"],"correct":0,"explanation":"Ngay sau khi nói đi xe buýt, người đó cho biết mình không có ô tô."}]}'),
    (38, 16, 'A2 · Cắm trại mùa hè', 37.92, '{"facts":[{"id":"F1","text":"Người nói dự định thăm ông bà vào mùa hè."},{"id":"F2","text":"Họ sẽ cắm trại gần nhà ông bà."},{"id":"F3","text":"Họ sẽ cắm trại bên hồ, không ở trong cabin."},{"id":"F4","text":"Người nói thấy nơi đó đẹp và mong chuyến đi vui."}],"questions":[{"id":"Q1","type":"MAIN_IDEA","text":"Kế hoạch mùa hè được nhắc tới là gì?","options":["Thăm ông bà và cắm trại","Đi học ở thành phố khác","Ở nhà làm việc"],"correct":0,"explanation":"Người nói sẽ thăm ông bà và đi cắm trại."},{"id":"Q2","type":"DETAIL","text":"Họ sẽ ở gần nhà ai?","options":["Ông bà","Bạn bè","Giáo viên"],"correct":0,"explanation":"Khu cắm trại nằm gần nhà ông bà."},{"id":"Q3","type":"DETAIL","text":"Họ dự định ngủ ở đâu?","options":["Cắm trại bên hồ","Trong cabin","Trong khách sạn"],"correct":0,"explanation":"Người nói bác bỏ cabin và chọn cắm trại bên hồ."},{"id":"Q4","type":"INFERENCE","text":"Người nói có thái độ thế nào với chuyến đi?","options":["Mong chờ chuyến đi","Lo sợ chuyến đi","Không muốn đi"],"correct":0,"explanation":"Người đó nói nơi ấy đẹp và chuyến đi sẽ rất vui."},{"id":"Q5","type":"SPEAKER_INTENT","text":"Người kia chúc chuyến đi vui để làm gì?","options":["Thể hiện sự quan tâm","Hủy kế hoạch cắm trại","Hỏi mượn đồ dùng"],"correct":0,"explanation":"Lời chúc là phản hồi thân thiện sau khi nghe kế hoạch."}]}'),
    (41, 13, 'B1 · Tiếng Pháp và công việc cũ', 34.5, '{"facts":[{"id":"F1","text":"Người nói hiện chỉ nói được một ít tiếng Pháp."},{"id":"F2","text":"Trước đây người đó dùng tiếng Pháp thường xuyên khi làm cho một công ty Pháp."},{"id":"F3","text":"Sau khi đổi việc, người đó không còn dùng tiếng Pháp nhiều."},{"id":"F4","text":"Trước đây người đó đến Pháp mỗi năm một lần vì công việc."}],"questions":[{"id":"Q1","type":"MAIN_IDEA","text":"Vì sao việc sử dụng tiếng Pháp của người nói thay đổi?","options":["Người đó đổi công việc","Người đó chuyển đến Pháp","Người đó bắt đầu học tiếng Tây Ban Nha"],"correct":0,"explanation":"Người đó từng làm cho công ty Pháp rồi đổi việc."},{"id":"Q2","type":"DETAIL","text":"Người đó từng làm cho loại công ty nào?","options":["Công ty Pháp","Công ty Đức","Trường học"],"correct":0,"explanation":"Người đó nói mình từng làm cho một công ty Pháp."},{"id":"Q3","type":"DETAIL","text":"Trước đây người đó đến Pháp bao lâu một lần?","options":["Mỗi năm một lần","Mỗi tháng một lần","Chưa từng đến"],"correct":0,"explanation":"Người đó từng đến Pháp một lần mỗi năm vì công việc."},{"id":"Q4","type":"INFERENCE","text":"Điều gì có thể khiến người đó ít nói tiếng Pháp hơn bây giờ?","options":["Công việc mới ít cần tiếng Pháp","Người đó quên hoàn toàn tiếng Pháp","Pháp ngừng đón khách"],"correct":0,"explanation":"Việc sử dụng tiếng Pháp giảm sau khi người đó đổi việc."},{"id":"Q5","type":"SPEAKER_INTENT","text":"Câu Lucky you thể hiện điều gì?","options":["Ngưỡng mộ cơ hội được đến Pháp","Phàn nàn về công việc","Xin đi cùng chuyến sau"],"correct":0,"explanation":"Người kia tỏ ra thích thú khi nghe về các chuyến công tác ở Pháp."}]}'),
    (43, 35, 'B1 · Học từ vựng tiếng Tây Ban Nha', 34.6, '{"facts":[{"id":"F1","text":"Lời khuyên đầu tiên là học từ mới mỗi ngày."},{"id":"F2","text":"Người tư vấn gợi ý dùng ứng dụng từ vựng."},{"id":"F3","text":"Người tư vấn đề xuất học mười từ mỗi ngày."},{"id":"F4","text":"Người tư vấn không khuyến khích học năm mươi từ một ngày vì sẽ khó nhớ."},{"id":"F5","text":"Người học đồng ý làm theo lời khuyên."}],"questions":[{"id":"Q1","type":"MAIN_IDEA","text":"Lời khuyên chính trong cuộc trò chuyện là gì?","options":["Học từ mới đều đặn với lượng vừa phải","Chỉ học ngữ pháp","Học năm mươi từ mỗi ngày"],"correct":0,"explanation":"Người tư vấn đề nghị học từ mới hằng ngày và tránh học quá nhiều một lúc."},{"id":"Q2","type":"DETAIL","text":"Người tư vấn đề xuất học bao nhiêu từ mỗi ngày?","options":["Mười từ","Năm mươi từ","Một trăm từ"],"correct":0,"explanation":"Người tư vấn nói nên thử học mười từ một ngày."},{"id":"Q3","type":"DETAIL","text":"Công cụ nào được gợi ý?","options":["Ứng dụng từ vựng","Sách nấu ăn","Phim không phụ đề"],"correct":0,"explanation":"Người tư vấn gợi ý tải ứng dụng từ vựng."},{"id":"Q4","type":"INFERENCE","text":"Vì sao người tư vấn phản đối mục tiêu năm mươi từ mỗi ngày?","options":["Quá nhiều nên khó nhớ","Ứng dụng không có đủ từ","Không cần học tiếng Tây Ban Nha"],"correct":0,"explanation":"Người đó nói học quá nhiều một lúc sẽ không nhớ được."},{"id":"Q5","type":"SPEAKER_INTENT","text":"Người tư vấn nói không nên làm quá nhiều một lúc để làm gì?","options":["Giúp người học chọn mục tiêu thực tế","Kết thúc cuộc trò chuyện ngay","Khuyên bỏ học"],"correct":0,"explanation":"Đó là lời khuyên để người học ghi nhớ từ tốt hơn."}]}'),
    (46, 16, 'B2 · Đổi địa điểm đám cưới', 43.4, '{"facts":[{"id":"F1","text":"Phần lớn việc chuẩn bị đám cưới đã hoàn tất."},{"id":"F2","text":"Địa điểm bên hồ mong muốn không đặt được."},{"id":"F3","text":"Đám cưới sẽ diễn ra tại một khách sạn ở vùng nông thôn."},{"id":"F4","text":"Hai người tổ chức thấy phương án mới ổn và đặt được dịch vụ ăn uống với giá tốt."}],"questions":[{"id":"Q1","type":"MAIN_IDEA","text":"Cuộc trò chuyện tập trung vào điều gì?","options":["Kế hoạch đám cưới sau khi đổi địa điểm","Cách nấu ăn cho đám cưới","Một chuyến nghỉ dưỡng bên hồ"],"correct":0,"explanation":"Họ nói về tiến độ tổ chức, địa điểm mới và dịch vụ ăn uống."},{"id":"Q2","type":"DETAIL","text":"Địa điểm ban đầu họ muốn là ở đâu?","options":["Bên hồ","Trong thành phố","Trên bãi biển"],"correct":0,"explanation":"Họ dự tính tổ chức ở hồ nhưng không đặt được địa điểm mong muốn."},{"id":"Q3","type":"DETAIL","text":"Địa điểm mới là gì?","options":["Khách sạn ở vùng nông thôn","Nhà hàng trong trung tâm","Nhà người thân"],"correct":0,"explanation":"Người nói cho biết đám cưới sẽ ở khách sạn vùng nông thôn."},{"id":"Q4","type":"DETAIL","text":"Họ có lợi ích gì với bên cung cấp đồ ăn?","options":["Được mức giá tốt","Được miễn phí hoàn toàn","Phải đổi nhà cung cấp"],"correct":0,"explanation":"Người nói bảo đã nhận được một thỏa thuận giá tốt từ bên cung cấp đồ ăn."},{"id":"Q5","type":"INFERENCE","text":"Người tổ chức nhìn nhận sự thay đổi địa điểm thế nào?","options":["Cuối cùng mọi việc vẫn ổn","Đám cưới bị hủy","Họ rất thất vọng về khách sạn"],"correct":0,"explanation":"Người nói rằng cuối cùng mọi việc đã diễn ra tốt đẹp."}]}'),
    (48, 1, 'B2 · Dự định đến châu Âu', 28.28, '{"facts":[{"id":"F1","text":"Người nói chưa thực sự du lịch châu Âu; chỉ từng quá cảnh ở Paris."},{"id":"F2","text":"Người kia cho rằng quá cảnh không tính là đã thăm châu Âu."},{"id":"F3","text":"Người nói hy vọng sẽ đi châu Âu vào năm sau."},{"id":"F4","text":"Người đó dự tính đến Tây Ban Nha và người kia đánh giá đây là điểm đến đáng thăm."}],"questions":[{"id":"Q1","type":"MAIN_IDEA","text":"Hai người chủ yếu nói về điều gì?","options":["Kinh nghiệm và dự định du lịch châu Âu","Lịch bay bị hủy ở Paris","Cách học tiếng Tây Ban Nha"],"correct":0,"explanation":"Họ trao đổi về lần quá cảnh ở Paris và kế hoạch đến Tây Ban Nha."},{"id":"Q2","type":"DETAIL","text":"Người nói từng quá cảnh ở đâu?","options":["Paris","Madrid","Rome"],"correct":0,"explanation":"Người đó nói mình từng có một lần quá cảnh ở Paris."},{"id":"Q3","type":"DETAIL","text":"Người nói dự định đến quốc gia nào?","options":["Tây Ban Nha","Pháp","Đức"],"correct":0,"explanation":"Người đó đang dự tính đến Tây Ban Nha."},{"id":"Q4","type":"INFERENCE","text":"Vì sao người kia nói lần trước không tính?","options":["Chỉ quá cảnh, chưa thực sự tham quan","Chuyến bay kéo dài quá lâu","Người nói chưa từng lên máy bay"],"correct":0,"explanation":"Chỉ dừng ở sân bay Paris nên người kia không xem đó là một chuyến thăm."},{"id":"Q5","type":"SPEAKER_INTENT","text":"Người kia nói Spain is definitely worth the visit để làm gì?","options":["Khuyến khích chọn Tây Ban Nha","Cảnh báo không nên đến đó","Hỏi giá vé máy bay"],"correct":0,"explanation":"Người kia bày tỏ sự tán thành với kế hoạch đến Tây Ban Nha."}]}')
) AS seed(lesson_id, first_sentence_position, title, duration_seconds, content_json)
JOIN lessons lesson ON lesson.id = seed.lesson_id AND lesson.active = TRUE
JOIN lesson_sentences sentence ON sentence.lesson_id = seed.lesson_id
    AND sentence.position_index = seed.first_sentence_position
    AND sentence.audio_url IS NOT NULL
WHERE NOT EXISTS (
    SELECT 1 FROM listening_units existing
    WHERE existing.lesson_id = seed.lesson_id AND existing.audio_url = sentence.audio_url
);
